<script setup lang="ts">
import { Plus, ArrowUpRight, FileText, Search, LockKeyhole, Eye, BookOpen } from 'lucide-vue-next'
import type { Draft } from '#shared/content'
const selected = ref<string[]>([]); const bulkAction = ref('tag-add'); const target = ref(''); const bulkBusy = ref(false); const bulkMessage = ref('')
const route = useRoute(); const query = ref(''); const status = ref('all')
const { data: records, refresh, error } = await useAdminData<Draft[]>('/api/admin/content', [])
const { data: workspace } = await useAdminWorkspace()
const type = computed(() => workspace.value?.terms.find(t => t.kind === 'type' && t.id === route.query.kind))
const list = computed(() => (records.value || []).filter(d => (!type.value || d.kind === type.value.id) && (status.value === 'all' || (status.value === 'public' ? d.visibility === 'public' : d.visibility === 'private')) && `${d.title} ${d.body} ${d.tags.join(' ')}`.toLocaleLowerCase().includes(query.value.toLocaleLowerCase())))
const bulkOptions = computed(() => workspace.value?.terms.filter(t => t.kind === (bulkAction.value === 'category' ? 'category' : 'tag')) || [])
watch(bulkAction, () => { target.value = '' })
watch([query, status, () => route.query.kind], () => { selected.value = [] })
function toggle(id: string) { selected.value = selected.value.includes(id) ? selected.value.filter(x => x !== id) : [...selected.value, id].slice(0, 200) }
function toggleAll() { selected.value = selected.value.length === Math.min(list.value.length, 200) ? [] : list.value.slice(0, 200).map(d => d.id) }
async function applyBulk() {
  bulkBusy.value = true; bulkMessage.value = ''
  try { const result = await $fetch<{ updated: number }, string>('/api/admin/bulk', { method: 'POST', body: { action: bulkAction.value, targetId: target.value || null, items: (records.value || []).filter(d => selected.value.includes(d.id)).map(d => ({ id: d.id, revision: d.revision })) } }); selected.value = []; bulkMessage.value = `已更新 ${result.updated} 项内容的组织信息`; await refresh() }
  catch (e: any) { bulkMessage.value = e.data?.statusMessage || '批量操作失败'; await refresh() }
  finally { bulkBusy.value = false }
}
const title = computed(() => type.value?.name || '内容工作台')
useSeoMeta({ title: () => `${title.value} — XIAOJUESHI` })
function typeName(kind: string) { return workspace.value?.terms.find(t => t.id === kind && t.kind === 'type')?.name || kind }
function openNew() { return navigateTo({ path: '/admin/write', query: type.value ? { kind: type.value.id } : {} }) }
</script>
<template><AdminShell><main class="workspace-page"><div class="workspace-page-heading"><div><div class="page-eyebrow">CONTENT</div><h1>{{ title }}</h1><p>统一管理文章、随笔和笔记。通过知识库组织阅读结构。</p></div><button class="button button-dark" @click="openNew"><Plus :size="16" />新建记录</button></div><div class="content-toolbar"><div class="segmented" aria-label="发布状态"><button v-for="option in [{ id: 'all', name: '全部' }, { id: 'public', name: '已发布' }, { id: 'private', name: '私密' }]" :key="option.id" :class="{ active: status === option.id }" @click="status = option.id">{{ option.name }}</button></div><label class="workspace-search"><Search :size="16" /><input v-model="query" placeholder="搜索标题、正文或标签" aria-label="搜索后台内容" /></label></div><div class="list-caption"><label class="select-all"><input type="checkbox" :checked="list.length > 0 && selected.length === Math.min(list.length, 200)" :disabled="!list.length" aria-label="选择当前列表（最多200项）" @change="toggleAll" />{{ list.length }} 项内容</label><NuxtLink to="/admin/organize">管理类型、分类与标签 <ArrowUpRight :size="13" /></NuxtLink></div><p v-if="bulkMessage" class="notice" role="status">{{ bulkMessage }}</p><div v-if="selected.length" class="bulk-toolbar"><span>已选 {{ selected.length }} 项</span><select v-model="bulkAction" aria-label="批量操作"><option value="tag-add">添加标签</option><option value="tag-remove">移除标签</option><option value="category">设置分类</option></select><select v-model="target" aria-label="批量目标"><option value="">{{ bulkAction === 'category' ? '未分类' : '请选择标签' }}</option><option v-for="option in bulkOptions" :key="option.id" :value="option.id">{{ option.name }}</option></select><button class="button button-dark" :disabled="bulkBusy || (bulkAction !== 'category' && !target)" @click="applyBulk">应用</button><button class="subtle-button" @click="selected = []">取消选择</button><p>仅更新组织信息；公开版本同步更新分类标签，正文与发布状态不变。</p></div><div v-if="error" class="notice" role="alert">加载失败，请重试。<button @click="refresh()">重新加载</button></div><div class="workspace-content-list"><div v-for="record in list" :key="record.id" class="workspace-content-item"><input class="row-selection" type="checkbox" :checked="selected.includes(record.id)" :aria-label="`选择${record.title}`" @change="toggle(record.id)" /><NuxtLink :to="`/admin/write?id=${record.id}`" class="workspace-content-row" data-testid="content-row"><span class="record-icon"><component :is="record.kind === 'note' ? BookOpen : FileText" :size="18" /></span><div class="workspace-record-text"><h2>{{ record.title }}</h2><div><span>{{ typeName(record.kind) }}</span><span>·</span><span>{{ record.category || '未分类' }}</span><span>·</span><time>{{ record.updatedAt.slice(0,10) }}</time></div><div v-if="record.tags.length" class="workspace-record-tags"><span v-for="tag in record.tags" :key="tag"># {{ tag }}</span></div></div><span class="visibility-badge" :class="record.visibility"><Eye v-if="record.visibility === 'public'" :size="12" /><LockKeyhole v-else :size="12" />{{ record.visibility === 'public' ? '已发布' : '私密' }}</span><ArrowUpRight class="record-end-arrow" :size="16" /></NuxtLink></div></div><div v-if="!list.length && !error" class="empty-state"><FileText :size="28" /><h2>{{ query ? '没有匹配的内容' : '暂无内容' }}</h2><p>新内容默认私密，保存不会自动发布。</p><button class="button button-dark" @click="openNew">新建记录 <Plus :size="16" /></button></div></main></AdminShell></template>
